DEFERRED={'anhydrous':'较专门化学形容词，通用学习暂略。','dono':'低频网络截短形式，优先 donation。','donator':'较少用的捐赠者名称，优先 donor。','donative':'较专门或古旧的赠礼名词、形容词，暂略。','donatory':'罕用赠与相关词，暂略。','gloriation':'古旧、罕用夸耀名词，优先 glorification。','gloriole':'较专门光环、微小荣誉词，暂略。'}
PUBLIC_ROOT=dict(id='C1163',meaning='公众、公共；公开、出版与共和国',core='从个人手里、私人圈子里，走向社会大众能参与、能看到的范围。',image='拉丁 populus 民众 → publicus 公共的；publicare 使公开 → publish / publication；publicitas 公开状态 → publicity；res publica 公共事务 → republic。',intro='public 让人想到公众；publish 把内容送到读者面前；publicity 说关注和宣传。它们并不是一个词加不同尾巴这么简单：publish、publication、publicity 各有拉丁和法语路线。republic 开头来自 res 事务，不是再次的 re-。',forms='public 末尾 c 读 /k/，publicity、publicize、publicist 中 c 读 /s/；publish 则有中古英语词形改造。publicly 直接加 -ly。republican 作普通词与大写政党名称时要分清语境。',branches=[['面向公众','public, publicly'],['出版、发行与成品','publish, publisher, publishing, publication, republication'],['宣传与关注','publicity, publicize, publicist'],['公共事务与政体名称','republic, republican']],contrasts='publish 可以只是发布，publicize 进一步让人注意；publisher 负责出版发行，publicist 负责宣传。public 不等于免费，republic 也不自动说明一个国家实际运行的全部特点。',practice='用 publish、publication、publicity 描述一本书从发布到受到关注；区分 publicly funded 与 publicly available；说明 republic 不能拆成再次公开。',words=list(ASSIGN['roots'][86]['family']),exclude={})
AN_ROOT=dict(id='C0051',meaning='不、没有；缺少某种状态或特征',core='先认出后半部分是什么，再看 a- / an- 把哪项特征拿掉；现代词义不能只靠字面推断。',image='an- + 名字 → anonymous；a- + 神 → atheos → atheist / atheism；an- + 感觉 → anesthesia；a- + 节奏 → arrhythmia；a- + 典型 → atypical。',intro='希腊否定前缀常见 a-，元音前常见 an-。ar-、am- 不应被当作见到就能否定的万能拼块，arrhythmia 和 ambrosia 有各自古典构词历史。anesthesia、anemia 的现代医学义比无感觉、无血这类字面义精确；务必看具体词条。',forms='anonymous 与 anonymity 的重音不同；atheist 在英语中早于 atheism，各有法语借入历史。agnostic 是19世纪造词。anesthesia、anemia、anemic 的英式拼写分别是 anaesthesia、anaemia、anaemic。',branches=[['姓名与身份','anonymous, anonymously, anonymity, anonymize'],['神、信仰与可知性','atheism, atheist, atheistic, agnostic, agnosticism'],['统治与政治立场〔共享〕','anarchy, anarchist, anarchism, anarchic, apolitical'],['感觉、语言与身体状态','anesthesia, anemia, anemic, arrhythmia, aphasia, asymptomatic'],['氧与生命过程','anaerobic'],['典型、情感和道德框架〔共享〕','atypical, atypically, apathy, apathetic, amoral'],['不朽者的食物','ambrosia']],contrasts='anonymous 不公开身份，private 不向公众开放；atheism 与 agnosticism 关注信仰和可知性两个角度；asymptomatic 只说无症状，不等于无疾病。anarchy 的政治理论义和日常混乱义须按语境分开。',practice='解释为什么 anonymous、anemia 都有 an-，却不能照字面硬译；比较公开匿名发文与私下署名发文；用 atypical 与 asymptomatic 说明两种不同的否定范围。',words=[w for w in ASSIGN['roots'][87]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][87]['family'] if w in DEFERRED})
DON_ROOT=dict(id='C0340',meaning='给出、赠与；捐赠、宽免与纵容',core='给出去的不只是钱物，也可以是原本要追究的处罚或过错；放过去，便有宽恕和容忍。',image='拉丁 donum 礼物 → donare 赠与 → donatio → donation → 反构 donate；donator → donor；perdonare 宽免 → pardon；condonare 免除 → condone。',intro='donation、donor 都比英语 donate 更早，不能看到动词就默认名词都从它产生。pardon 的名词、动词分别经法语传入。condone 由宽免走向容忍不当行为，现代常带批评意味；这里的 con- 不必硬译成一起。',forms='donate 常见英式后重音、美式前重音；donation 重音在 -na-，donor 重音在开头。pardonable 可以原谅，unpardonable 不可原谅；condonation 与 condemnation 谴责拼写接近，方向却不同。',branches=[['钱物、时间与帮助','donation, donate, donor'],['原谅与赦免','pardon, pardonable, unpardonable'],['放过不当行为','condone, condonation']],contrasts='donor 是提供者，recipient 是接收者。pardon 可说宽恕、赦免；condone 更常说对不当行为姑息或默许。理解原因不等于纵容行为。',practice='把 donate、donation、donor 放入同一件公益活动里；分别用 pardon 和 condone 说明原谅一个人与放行错误行为的区别。',words=[w for w in ASSIGN['roots'][88]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][88]['family'] if w in DEFERRED})
GLOR_ROOT=dict(id='C0488',meaning='荣耀、名望、赞美；壮丽与美化',core='把某个人、成就或景象照得很有光彩；光彩可以是真的，也可能只是过度包装。',image='拉丁 gloria 荣誉 → glory；gloriosus → glorious；glorificare 使有荣光 → glorify；vana gloria 空洞荣耀 → vainglory。',intro='本组从拉丁 gloria 开始，更早来源没有定论，不强接到 gnosc 的知道词根。glory 的名词、动词有分别借入的路线；glorious、glorification 也并非只由现代英语 glory、glorify 加尾巴生成。',forms='glorious 常真心说光荣、美好；glorified 在名词前却常拆穿包装。glorify 的过去分词是 glorified，y 变 i。vainglory 的英美常见重音不同，vainglorious 通常重读 -glor-。',branches=[['荣耀、壮丽与赞叹','glory, glorious, gloriously'],['颂扬与过度美化','glorify, glorification, glorified'],['不光彩的结果','inglorious'],['空洞荣耀与自负','vainglory, vainglorious']],contrasts='fame 是名气，glory 还带荣誉；glorious 是赞叹，glorified 常是讽刺。pride 可能健康，vainglory 明显批评虚荣。glorify violence 是美化暴力，不是中性地描写它。',practice='用 glorious 描写景色，用 glorified 批评徒有包装的工具；解释 glory 与 vainglory 的评价差别；读出 glorify 与 glorification 的重音。',words=[w for w in ASSIGN['roots'][89]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][89]['family'] if w in DEFERRED})
